// ── Builder (Android `DimenInterpolated` / `InterpolatedSp`). ───────────────────────────
/** Custom-dimension builder for the interpolated strategy. */
export class DimenInterpolated extends DimenBuilder {
  get isdp(): number { return this.sdp; }
  get isdpPx(): number { return this.sdpPx; }
  get issp(): number { return this.ssp; }
  get isspPx(): number { return this.sspPx; }
  get isem(): number { return this.sem; }
  get isemPx(): number { return this.semPx; }
  get ihdp(): number { return this.hdp; }
  get ihdpPx(): number { return this.hdpPx; }
  get ihsp(): number { return this.hsp; }
  get ihspPx(): number { return this.hspPx; }
  get ihem(): number { return this.hem; }
  get ihemPx(): number { return this.hemPx; }
  get iwdp(): number { return this.wdp; }
  get iwdpPx(): number { return this.wdpPx; }
  get iwsp(): number { return this.wsp; }
  get iwspPx(): number { return this.wspPx; }
  get iwem(): number { return this.wem; }
  get iwemPx(): number { return this.wemPx; }
}
/** Starts a builder: `interpolatedDp(16).screen(UiModeType.TELEVISION, 40).isdp`. */
export const interpolatedDp = (value: number): DimenInterpolated => new DimenInterpolated(B, value);
/** Text builder (same class; read `.issp` / `.isem`). */
export const interpolatedSp = (value: number): DimenInterpolated => new DimenInterpolated(B, value);
